window.GUIDE = {"revision":"38ee1626f + local changes","chapters":[{"id":"overview","group":"เริ่มต้น","title":"ภาพรวมงานที่ต้องอธิบาย","intro":"Calibration คือการเชื่อมภาพจากกล้องกับพื้นที่บนพื้น ส่วน Lot Model คือแผนผังสถานที่ที่ใช้แสดงผล ทั้งสองส่วนเชื่อมกัน แต่มีหน้าที่คนละอย่าง","steps":[["หน้าเว็บ","React รับภาพ การคลิกจุด การแก้แถว และการแก้แผนผัง ส่งข้อมูลไปให้ API"],["Vision API","Python ตรวจภาพ ตรวจ geometry แปลงพิกัด คำนวณพื้นที่และช่องว่าง"],["LIFF","อ่านข้อมูลที่เผยแพร่และแสดงแผนผังให้นักศึกษา ไม่คำนวณว่าที่ไหนจอดได้เอง"]],"files":[{"path":"tools/calibration-ui/components/dashboard/DashboardClient.tsx","line":10,"code":"export function DashboardClient({ initialView = 'PARKING', initialSetupTab = 'camera' }: { initialView?: View; initialSetupTab?: 'camera' | 'lot' | 'routes' }) {\n  const [view, setView] = useState<View>(initialView);\n  const [visited, setVisited] = useState(() => new Set<View>([initialView]));\n  const open = (next: View) => { setView(next); setVisited((old) => new Set([...old, next])); };\n  return (\n    <main className=\"min-h-screen bg-slate-50 text-slate-950\">\n      <header className=\"border-b border-slate-200 bg-white\">\n        <div className=\"mx-auto flex max-w-[1600px] flex-wrap items-center justify-between gap-4 px-5 py-5 sm:px-8\"><ParkMapBrand /><nav className=\"flex rounded-xl bg-slate-100 p-1\" aria-label=\"ParkMap areas\">\n          <button type=\"button\" aria-pressed={view === 'PARKING'} onClick={() => open('PARKING')} className={`rounded-lg px-4 py-2 text-sm font-semibold ${view === 'PARKING' ? 'bg-white text-blue-700 shadow-sm' : 'text-slate-600'}`}>Parking</button>\n          <button type=\"button\" aria-pressed={view === 'SETUP'} onClick={() => open('SETUP')} className={`rounded-lg px-4 py-2 text-sm font-semibold ${view === 'SETUP' ? 'bg-white text-blue-700 shadow-sm' : 'text-slate-600'}`}>Setup</button>\n          <button type=\"button\" aria-pressed={view === 'LABEL'} onClick={() => open('LABEL')} className={`rounded-lg px-4 py-2 text-sm font-semibold ${view === 'LABEL' ? 'bg-white text-blue-700 shadow-sm' : 'text-slate-600'}`}>Label</button>\n        </nav></div>\n      </header>\n      <div className={`mx-auto px-5 py-6 sm:px-8 lg:py-8 ${view === 'PARKING' ? 'max-w-6xl' : 'max-w-[1600px]'}`}>\n        {visited.has('PARKING') && <div hidden={view !== 'PARKING'}><ImageAnalyzer onOpenSetup={() => open('SETUP')} /></div>}\n        {visited.has('SETUP') && <div hidden={view !== 'SETUP'}><SetupWorkspace initialTab={initialSetupTab} /></div>}\n        {visited.has('LABEL') && <div hidden={view !== 'LABEL'}><AnnotationWorkspace /></div>}\n      </div>\n    </main>\n  );"}],"question":"Calibration กับ Lot Model ต่างกันอย่างไร?","answer":"Calibration เชื่อมพิกัดภาพกับระนาบพื้น ส่วน Lot Model เก็บแผนผังและ landmark สำหรับแสดงสถานที่ การเปลี่ยนมุมดู 3D ไม่ได้สร้างหลักฐานว่าพื้นที่ว่าง","caution":"คู่มือนี้อธิบายส่วนที่คุณระบุว่ารับผิดชอบ และโค้ดที่เชื่อมต่อ ไม่ใช่การยืนยันผู้เขียนทุกไฟล์"},{"id":"image","group":"Calibration","title":"01 · เริ่มจากภาพหนึ่งภาพ","intro":"หน้า Parking เริ่มโดยไม่มีภาพ ผู้ใช้ต้องเลือกภาพหรือวิดีโอก่อน จึงมีข้อมูลให้วิเคราะห์","steps":[["เก็บ state","file เก็บไฟล์ที่เลือก ส่วน previewUrl เก็บ URL ชั่วคราวสำหรับแสดงภาพ"],["แสดงตัวอย่าง","URL.createObjectURL สร้าง URL ในเบราว์เซอร์ ไม่ใช่การอัปโหลดภาพไป API"],["Analyze","เมื่อวิเคราะห์จึงส่งภาพผ่านเส้นทาง proxy ไป Python ผลลัพธ์กลับมาอยู่ใน state และส่งต่อให้ component แสดงผล"]],"files":[{"path":"tools/calibration-ui/components/camera/ImageAnalyzer.tsx","line":13,"code":"export function ImageAnalyzer({ onOpenSetup }: { onOpenSetup: () => void }) {\n  const [file, setFile] = useState<File | null>(null);\n  const [selectedDetector, setSelectedDetector] = useState<ParkingDetector | null>(null);\n  const [clearanceMargin, setClearanceMargin] = useState(String(DEFAULT_CLEARANCE_MARGIN_M));\n  const clearanceMarginValue = Number(clearanceMargin);\n  const clearanceMarginValid = clearanceMargin !== '' && Number.isFinite(clearanceMarginValue) && clearanceMarginValue >= 0 && clearanceMarginValue <= MAX_CLEARANCE_MARGIN_M;\n  const [segmentationGaps, setSegmentationGaps] = useState<components['schemas']['SegmentationGapResult'] | null>(null);\n  const [segmentation, setSegmentation] = useState<components['schemas']['SegmentationExperimentResult'] | null>(null);\n  const [motorcycles, setMotorcycles] = useState<components['schemas']['MotorcycleProxy'][]>([]);\n  const [segmentationError, setSegmentationError] = useState('');\n  const [previewUrl, setPreviewUrl] = useState<string | null>(null);\n  const [videoUrl, setVideoUrl] = useState<string | null>(null);\n  const detector = selectedDetector ?? (videoUrl ? DEFAULT_VIDEO_DETECTOR : DEFAULT_IMAGE_DETECTOR);\n  const usesSegmentation = detector === 'yolo26n-seg';\n  const [analysis, setAnalysis] = useState<DetectionResponse | null>(null);\n  const [state, setState] = useState<'idle' | 'processing' | 'error' | 'done'>('idle');\n  const [error, setError] = useState<string | null>(null);\n  const [setupRequired, setSetupRequired] = useState(false);\n  const controllerRef = useRef<AbortController | null>(null);\n\n  useEffect(() => {\n    if (!file || videoUrl || !usesSegmentation) return;\n    const controller = new AbortController();\n    void getCalibration(controller.signal)\n      .then((savedCalibration) => {\n        setSetupRequired(!savedCalibration);\n      })\n      .catch((reason) => {"},{"path":"tools/calibration-ui/lib/lotModelEditorDevProxy.ts","line":18,"code":"export function lotModelEditorMiddleware(options: ProxyOptions) {\n  return (incoming: IncomingMessage, outgoing: ServerResponse, next: () => void) => {\n    const path = incoming.url?.split('?')[0];\n    if (path !== '/api/lot-model-editor' && path !== '/api/annotation' && path !== '/api/classifier') { next(); return; }\n    const headers = new Headers();\n    for (const [key, value] of Object.entries(incoming.headers)) {\n      if (value !== undefined) for (const part of Array.isArray(value) ? value : [value]) headers.append(key, part);\n    }\n    void (async () => {\n      const init: RequestInit & { duplex?: string } = { method: incoming.method, headers };\n      if (incoming.method !== 'GET' && incoming.method !== 'HEAD') {\n        init.body = Readable.toWeb(incoming) as unknown as ReadableStream<Uint8Array>;\n        init.duplex = 'half';\n      }\n      const request = new Request(new URL(incoming.url ?? '/', `http://${headers.get('Host') ?? '127.0.0.1:3000'}`), init);\n      const response = await (path === '/api/lot-model-editor' ? proxyLotModelRequest : proxyAnnotationRequest)(request, options);\n      outgoing.statusCode = response.status;\n      response.headers.forEach((value, name) => outgoing.setHeader(name, value));\n      outgoing.end(new Uint8Array(await response.arrayBuffer()));\n    })().catch(() => {\n      if (outgoing.headersSent || outgoing.destroyed) { outgoing.end(); return; }\n      outgoing.statusCode = 502; outgoing.setHeader('Content-Type', 'application/json');\n      outgoing.end(JSON.stringify({ detail: 'ติดต่อระบบแก้แผนผังไม่ได้ กรุณาตรวจหน้าต่าง Calibration UI' }));\n    });"}],"question":"ทำไมเปิด Parking ครั้งแรกไม่มีรูป?","answer":"previewUrl เริ่มเป็น null และไม่มีโค้ดโหลดรูปทดสอบให้อัตโนมัติ ต้องเลือกไฟล์ก่อน ภาพใน test-data มีไว้ให้สคริปต์ทดสอบ","caution":"ภาพที่ใช้ Calibration ต้องตรงกับความละเอียดและมุมกล้องที่นำไปวิเคราะห์"},{"id":"roi","group":"Calibration","title":"02 · ROI และแถวเสมือน","intro":"ROI คือขอบเขตในภาพที่จะวิเคราะห์ แถวคือพื้นที่ย่อยที่ช่วยจัดรถและหาช่องว่าง ไม่ใช่ช่องจอดที่ตีเส้นไว้","steps":[["วาด polygon","คลิกจุดต่อกันเพื่อกำหนด Parking ROI และแถวในภาพ"],["บันทึก","หน้าเว็บส่งโครงสร้างไป API เพื่อตรวจและบันทึก ไม่ใช่เพียงวาดเส้นบนหน้าจอ"],["ใช้ในการวิเคราะห์","ตำแหน่งรถและหลักฐาน mask ถูกนำไปพิจารณาว่าเกี่ยวข้องกับแถวใด"]],"files":[{"path":"tools/calibration-ui/components/setup/ParkingAreaSetup.tsx","line":17,"code":"export function ParkingAreaSetup({ imageUrl, dimensions, onImageChange, onRowsSaved }: Props) {\n  const [saved, setSaved] = useState<ParkingCalibration | null>(null);\n  const [shapes, setShapes] = useState<CalibrationShape[]>(shapesFromCalibration(null));\n  const [active, setActive] = useState(0);\n  const [message, setMessage] = useState<string | null>(null);\n  const [saving, setSaving] = useState(false);\n\n  useEffect(() => {\n    const controller = new AbortController();\n    void getCalibration(controller.signal).then((value) => { setSaved(value); setShapes(shapesFromCalibration(value)); }).catch((error) => setMessage(error instanceof Error ? error.message : 'Unable to load parking area.'));\n    return () => controller.abort();\n  }, []);\n\n  const complete = useMemo(() => shapes.length > 1 && shapes.every((shape) => shape.points.length >= 3), [shapes]);\n  const chooseImage = (file?: File) => {\n    if (!file) return;\n    const url = URL.createObjectURL(file);\n    const image = new Image();\n    image.onload = () => onImageChange(url, { width: image.naturalWidth, height: image.naturalHeight });\n    image.onerror = () => setMessage('Unable to load the reference image.');\n    image.src = url;\n  };\n  const addRow = () => {\n    const id = nextRowId(shapes.slice(1).map((shape) => shape.id));"},{"path":"tools/calibration-ui/components/setup/CalibrationCanvas.tsx","line":3,"code":"import { useRef, useState } from 'react';\nimport type { CalibrationPoint } from '@/types/calibration';\n\nexport interface CalibrationShape { id: string; label: string; points: CalibrationPoint[]; }\n\nexport function CalibrationCanvas({ imageUrl, imageWidth, imageHeight, shapes, activeIndex, onChange }: { imageUrl: string; imageWidth: number; imageHeight: number; shapes: CalibrationShape[]; activeIndex: number; onChange: (points: CalibrationPoint[]) => void }) {\n  const svgRef = useRef<SVGSVGElement | null>(null);\n  const [dragging, setDragging] = useState<number | null>(null);\n  const active = shapes[activeIndex];\n  const point = (clientX: number, clientY: number) => {\n    const bounds = svgRef.current!.getBoundingClientRect();\n    return { x: Math.min(1, Math.max(0, (clientX - bounds.left) / bounds.width)), y: Math.min(1, Math.max(0, (clientY - bounds.top) / bounds.height)) };\n  };\n  return <div className=\"flex min-h-96 items-center justify-center overflow-auto rounded-xl bg-slate-950 p-2\"><div className=\"relative inline-block max-h-full max-w-full select-none\"><img src={imageUrl} alt=\"Parking setup reference\" draggable={false} className=\"block max-h-[70vh] max-w-full object-contain\" /><svg ref={svgRef} viewBox={`0 0 ${imageWidth} ${imageHeight}`} preserveAspectRatio=\"none\" className=\"absolute inset-0 size-full cursor-crosshair touch-none\" aria-label={`Draw ${active.label}`} onPointerDown={(event) => { if (event.button === 0 && event.target === event.currentTarget) onChange([...active.points, point(event.clientX, event.clientY)]); }} onPointerMove={(event) => { if (dragging === null) return; const next = [...active.points]; next[dragging] = point(event.clientX, event.clientY); onChange(next); }} onPointerUp={() => setDragging(null)} onPointerCancel={() => setDragging(null)}>{shapes.map((shape, shapeIndex) => { const points = shape.points.map((item) => `${item.x * imageWidth},${item.y * imageHeight}`).join(' '); const selected = shapeIndex === activeIndex; return <g key={shape.id} className={selected ? 'text-cyan-300' : shapeIndex === 0 ? 'text-blue-400' : 'text-amber-300'}>{shape.points.length >= 3 ? <polygon points={points} className=\"pointer-events-none fill-current/10 stroke-current\" strokeWidth={Math.max(imageWidth, imageHeight) * (selected ? .003 : .002)} /> : <polyline points={points} fill=\"none\" className=\"pointer-events-none stroke-current\" strokeWidth={Math.max(imageWidth, imageHeight) * .003} />}{shape.points[0] && <text x={shape.points[0].x * imageWidth} y={Math.max(24, shape.points[0].y * imageHeight - 12)} className=\"pointer-events-none fill-current font-semibold\" fontSize={Math.max(18, imageHeight * .022)}>{shape.label}</text>}{shape.points.map((item, index) => <circle key={index} cx={item.x * imageWidth} cy={item.y * imageHeight} r={Math.max(8, Math.max(imageWidth, imageHeight) * (selected ? .006 : .004))} className={selected ? 'cursor-grab fill-white stroke-cyan-400' : 'pointer-events-none fill-current stroke-slate-950'} strokeWidth={Math.max(3, Math.max(imageWidth, imageHeight) * .002)} onPointerDown={selected ? (event) => { event.stopPropagation(); event.currentTarget.setPointerCapture(event.pointerId); setDragging(index); } : undefined} />)}</g>; })}</svg></div></div>;\n}\n"}],"question":"ROI กับ row ต่างกันอย่างไร?","answer":"ROI คือขอบเขตรวมของพื้นที่จอด ส่วน row คือบริเวณย่อยภายในพื้นที่สำหรับวิเคราะห์ ID ของ row เป็นรหัส geometry ภายใน ไม่ใช่หมายเลขช่องจอดจริง","caution":"อย่าแปลพื้นที่นอก ROI ว่าเป็นที่ว่าง ระบบไม่มีหลักฐานจากบริเวณนั้น"},{"id":"points","group":"Calibration","title":"03 · จุด P บอกระยะจริงได้อย่างไร","intro":"จุด P จับคู่ตำแหน่งที่คลิกในภาพกับพิกัดบนพื้นหน่วยเมตร ระยะจริงมาจากการวัดหรือข้อมูลที่ผู้ดูแลระบุ","steps":[["ฝั่งภาพ","image_x และ image_y ระบุจุดในภาพอ้างอิง"],["ฝั่งพื้น","ground_x_m และ ground_y_m ระบุพิกัดเมตรในระบบอ้างอิงที่เลือก"],["ที่มาของตัวเลข","MEASURED คือข้อมูลวัดจริง ESTIMATED คือข้อมูลประมาณ พร้อมบันทึกความไม่แน่นอนและที่มา"],["คำนวณ map","ต้องมีอย่างน้อย 4 จุดที่จัดวางเหมาะสมและไม่อยู่บนเส้นเดียวกัน ก่อนคำนวณ Homography"]],"files":[{"path":"tools/calibration-ui/components/setup/GroundMapSetup.tsx","line":10,"code":"export function GroundMapSetup({ imageUrl }: { imageUrl: string | null }) {\n  const [calibration, setCalibration] = useState<GroundPlaneCalibration | null>(null), [homography, setHomography] = useState<GroundPlaneHomographyResponse | null>(null);\n  const [message, setMessage] = useState<string | null>(null), [busy, setBusy] = useState(false), [provenance, setProvenance] = useState<MetricMeasurementSource | null>(null);\n  useEffect(() => { const controller = new AbortController(); void Promise.all([getGroundPlaneCalibration(controller.signal), getGroundPlaneHomography(controller.signal)]).then(([ground, map]) => { setCalibration(ground.calibration); setProvenance(ground.provenance); setHomography(map); }).catch((error) => setMessage(error instanceof Error ? error.message : 'Unable to load ground calibration.')); return () => controller.abort(); }, []);\n  const replace = (index: number, next: GroundControlPoint) => setCalibration((current) => current ? { ...current, control_points: current.control_points.map((point, pointIndex) => pointIndex === index ? next : point) } : current);\n  const update = (index: number, key: 'id' | 'image_x' | 'image_y' | 'ground_x_m' | 'ground_y_m', value: string) => setCalibration((current) => current ? { ...current, control_points: current.control_points.map((point, pointIndex) => pointIndex === index ? { ...point, [key]: key === 'id' ? value : Number(value) } : point) } : current);\n  const save = async () => { if (!calibration) return; const incomplete = calibration.control_points.find((point) => provenanceProblem(point)); if (incomplete) { setMessage(`${incomplete.id} ${provenanceProblem(incomplete)}.`); return; } setBusy(true); setMessage(null); try { const saved = await saveGroundPlaneCalibration(calibration); setCalibration(saved.calibration); setProvenance(saved.provenance); setMessage('Ground control points saved.'); } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to save ground calibration.'); } finally { setBusy(false); } };\n  const calculate = async () => { setBusy(true); setMessage(null); try { const result = await calculateGroundPlaneHomography(); setHomography(result); setMessage(result.status === 'VALIDATED' ? 'Map calibration ready.' : result.message); } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to calculate map calibration.'); } finally { setBusy(false); } };\n  if (!calibration) return <section className=\"rounded-2xl border border-slate-200 bg-white p-5 shadow-sm\"><h2 className=\"text-lg font-semibold\">Ground Map Calibration</h2><p className=\"mt-3 text-sm text-slate-500\">{message ?? 'Loading…'}</p></section>;\n  return <section className=\"rounded-2xl border border-slate-200 bg-white p-5 shadow-sm\"><div className=\"flex flex-wrap items-center justify-between gap-3\"><div><h2 className=\"text-lg font-semibold\">Ground Map Calibration</h2><p className=\"mt-1 text-sm text-slate-500\">Ground control points connect image positions to meters.</p>{provenance === 'ESTIMATED' && <p className=\"mt-2 rounded-lg bg-amber-50 px-3 py-2 text-sm text-amber-900\">Estimated calibration: usable for a recorded demo only. It makes no distance or accuracy claim, and a live camera shows every region as unknown until all inputs are measured.</p>}</div><span className={`rounded-full px-3 py-1 text-sm font-semibold ${homography?.current && homography.status === 'VALIDATED' ? 'bg-emerald-100 text-emerald-800' : 'bg-amber-100 text-amber-800'}`}>{homography?.current && homography.status === 'VALIDATED' ? 'Ready' : 'Needs update'}</span></div><GroundControlPointCanvas imageUrl={imageUrl} points={calibration.control_points} width={calibration.reference_image.width} height={calibration.reference_image.height} onSelect={(index) => document.getElementById(`ground-point-${index}`)?.focus()} /><div className=\"mt-4 space-y-2\">{calibration.control_points.map((point, index) => <div key={point.id} className=\"grid gap-2 rounded-xl bg-slate-50 p-3 sm:grid-cols-5\"><input id={`ground-point-${index}`} aria-label={`Point ${index + 1} ID`} value={point.id} onChange={(event) => update(index, 'id', event.target.value)} className=\"rounded-lg border px-3 py-2 text-sm\" />{(['image_x', 'image_y', 'ground_x_m', 'ground_y_m'] as const).map((key) => <label key={key} className=\"text-xs text-slate-500\">{key.replace('image_', 'Image ').replace('ground_', 'Ground ').replace('_m', ' (m)')}<input type=\"number\" step=\"any\" value={point[key]} onChange={(event) => update(index, key, event.target.value)} className=\"mt-1 w-full rounded-lg border px-3 py-2 text-sm text-slate-900\" /></label>)}<div className=\"sm:col-span-5\"><ProvenanceFields label={`Point ${index + 1}`} value={point} onChange={(next) => replace(index, next)} /></div></div>)}</div><div className=\"mt-4 flex flex-wrap justify-end gap-2\"><button type=\"button\" onClick={() => setCalibration((current) => current ? { ...current, control_points: [...current.control_points, { id: `P${current.control_points.length + 1}`, image_x: 0, image_y: 0, ground_x_m: 0, ground_y_m: 0, provenance: 'MEASURED' }] } : current)} className=\"rounded-lg border px-3 py-2 text-sm\">Add point</button><button type=\"button\" onClick={() => void save()} disabled={busy} className=\"rounded-lg border border-blue-600 px-4 py-2 text-sm font-semibold text-blue-700 disabled:opacity-50\">Save points</button><button type=\"button\" onClick={() => void calculate()} disabled={busy || calibration.control_points.length < 4} className=\"rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white disabled:opacity-50\">Calculate / update map</button></div>{message && <p role=\"status\" className=\"mt-3 text-sm text-slate-700\">{message}</p>}</section>;\n}\n\n"},{"path":"apps/vision-api/app/services/ground_plane_calibration_service.py","line":40,"code":"    def save(self, calibration: GroundPlaneCalibration) -> GroundPlaneCalibrationResponse:\n        self.config_directory.mkdir(parents=True, exist_ok=True)\n        temporary_path = None\n        try:\n            with tempfile.NamedTemporaryFile(mode=\"w\", encoding=\"utf-8\", dir=self.config_directory, prefix=\"ground_plane_calibration.\", suffix=\".tmp\", delete=False) as file:\n                temporary_path = Path(file.name)\n                json.dump(calibration.model_dump(mode=\"json\"), file, indent=2)\n                file.write(\"\\n\"); file.flush(); os.fsync(file.fileno())\n            os.replace(temporary_path, self.calibration_path)\n        finally:\n            if temporary_path is not None and temporary_path.exists(): temporary_path.unlink()\n        persisted = self.load()\n        if persisted.model_dump(mode=\"json\") != calibration.model_dump(mode=\"json\"):\n            raise OSError(\"Ground-plane calibration read-after-write verification failed.\")\n        return self.response(persisted)\n\n\nground_plane_calibration_service = GroundPlaneCalibrationService()\n"}],"question":"ระบบรู้ได้อย่างไรว่าในภาพห่างกัน 4 เมตร?","answer":"เพราะเราใส่พิกัดพื้นของจุดอ้างอิง เช่น (0,0) และ (4,0) ระบบไม่ได้รู้หน่วยเมตรจากภาพเอง","caution":"ใส่ระยะที่กะมาแล้วเลือก MEASURED ไม่ทำให้ข้อมูลกลายเป็นการวัดจริง"},{"id":"homography","group":"Calibration","title":"04 · Homography แปลงภาพเป็นพื้น","intro":"Homography คือ matrix 3×3 ที่เชื่อมระนาบภาพกับระนาบพื้น ใช้จุด P เป็นข้อมูลสำหรับคำนวณ","steps":[["สร้าง matrix","calculate_homography รับคู่จุดภาพกับจุดพื้น สร้างการแปลงแบบ projective"],["ฉายจุด","นำ (x,y,1) คูณ matrix แล้วหารด้วยพิกัดตัวท้ายเพื่อได้ตำแหน่งพื้น"],["ตรวจผล","บริการตรวจความเหมาะสมของข้อมูลและความสัมพันธ์กับ ROI/แถว ไม่ใช้ matrix ที่ไม่ผ่านการตรวจ"],["แปลงกลับ","inverse matrix ใช้ฉาย geometry บนพื้นกลับไปวาดทับภาพ"]],"files":[{"path":"apps/vision-api/app/services/ground_plane_homography_service.py","line":77,"code":"def transform_point(x: float, y: float, matrix: np.ndarray) -> tuple[float, float] | None:\n    projected = matrix @ np.array([x, y, 1.0])\n    if not np.all(np.isfinite(projected)) or abs(projected[2]) < 1e-10:\n        return None\n    result = projected[:2] / projected[2]\n    if not np.all(np.isfinite(result)):\n        return None\n    return float(result[0]), float(result[1])\n\n\ndef _metric_polygon(identifier: str, points, matrix: np.ndarray, measured=None) -> GroundPlaneMetricPolygon:\n    transformed = [transform_point(point.x, point.y, matrix) for point in points]\n    if any(point is None for point in transformed):\n        raise HomographyInputError(f\"{identifier} contains a vertex that cannot be projected.\")\n    metric = np.asarray(transformed, dtype=float)\n    centered = metric - metric.mean(axis=0)\n    _, _, vt = np.linalg.svd(centered, full_matrices=False)\n    axes = vt if len(vt) == 2 else np.eye(2)\n    extents = np.ptp(centered @ axes.T, axis=0)\n    longitudinal, cross = sorted((float(extents[0]), float(extents[1])), reverse=True)"},{"path":"apps/vision-api/app/services/ground_plane_homography_service.py","line":55,"code":"def calculate_homography(image: np.ndarray, ground: np.ndarray) -> np.ndarray:\n    _validate_points(image, ground)\n    image_n, image_t = _normalize(image)\n    ground_n, ground_t = _normalize(ground)\n    rows = []\n    for (x, y), (u, v) in zip(image_n, ground_n, strict=True):\n        rows.extend(([-x, -y, -1.0, 0.0, 0.0, 0.0, u * x, u * y, u], [0.0, 0.0, 0.0, -x, -y, -1.0, v * x, v * y, v]))\n    design = np.asarray(rows, dtype=float)\n    if np.linalg.matrix_rank(design) < 8:\n        raise HomographyInputError(\"Control-point configuration cannot determine a homography.\")\n    _, _, vt = np.linalg.svd(design)\n    normalized_h = vt[-1].reshape(3, 3)\n    matrix = np.linalg.inv(ground_t) @ normalized_h @ image_t\n    if abs(matrix[2, 2]) > 1e-12:\n        matrix /= matrix[2, 2]\n    else:\n        matrix /= np.linalg.norm(matrix)\n    if not np.all(np.isfinite(matrix)) or abs(np.linalg.det(matrix)) < 1e-12 or np.linalg.cond(matrix) > 1e12:\n        raise HomographyInputError(\"Calculated homography is singular or numerically unstable.\")\n    return matrix\n"}],"question":"ทำไมไม่ใช้จำนวนพิกเซลต่อเมตรค่าเดียวทั้งภาพ?","answer":"มุมกล้องทำให้ของไกลดูเล็กและของใกล้ดูใหญ่ สเกลจึงเปลี่ยนตามตำแหน่ง Homography ช่วยคำนวณบนระนาบพื้นตามตำแหน่งนั้น","caution":"การแปลงนี้ไม่ใช่การสร้างโมเดล 3D ของรถ และไม่ทำให้จุดบนกระจกหรือเบาะกลายเป็นจุดบนพื้นจริง"},{"id":"dimensions","group":"Calibration","title":"05 · ขนาดแถวและการตรวจความถูกต้อง","intro":"นอกจากจุด P ระบบยังรับความยาวและความกว้างของแถว พร้อมที่มาและความไม่แน่นอน เพื่อตรวจ geometry ที่ใช้วิเคราะห์","steps":[["อ่านแถวที่มี","โหลด row IDs จาก Parking Calibration ก่อนรับขนาดของแต่ละแถว"],["ใส่ขนาดเมตร","เก็บ length_m และ width_m ของแถว ไม่ใช่ขนาด pixel"],["ตรวจและบันทึก","ตรวจแหล่งที่มาและข้อมูลที่จำเป็น ก่อนส่งให้ backend เก็บไว้ใช้ตรวจแผนที่พื้น"]],"files":[{"path":"tools/calibration-ui/components/setup/PhysicalDimensionsSetup.tsx","line":13,"code":"export function PhysicalDimensionsSetup() {\n  const [calibration, setCalibration] = useState<GroundPlaneCalibration | null>(null);\n  const [rowIds, setRowIds] = useState<MetricRowId[]>([]);\n  const [message, setMessage] = useState<string | null>(null);\n  const [saving, setSaving] = useState(false);\n  useEffect(() => {\n    const controller = new AbortController();\n    void getCalibration(controller.signal).then((parking) => {\n      setRowIds(sortRowIds(parking?.rows ?? []).map((row) => row.id));\n      if (!parking) {\n        setMessage('ตั้งค่า Parking Area และบันทึกอย่างน้อยหนึ่งแถวก่อนกรอกขนาดจริง');\n        return null;\n      }\n      return getGroundPlaneCalibration(controller.signal).then((ground) => setCalibration(ground.calibration));\n    }).catch((error) => setMessage(error instanceof Error ? error.message : 'Unable to load dimensions.'));\n    return () => controller.abort();\n  }, []);\n  const replace = (id: MetricRowId, row: GroundMeasuredRow) => setCalibration((current) => current ? { ...current, measured_rows: { ...current.measured_rows, [id]: row } } : current);\n  const update = (id: MetricRowId, key: 'length_m' | 'width_m', value: string) => setCalibration((current) => current ? { ...current, measured_rows: { ...current.measured_rows, [id]: { ...(current.measured_rows[id] ?? EMPTY_ROW), [key]: value === '' ? null : Number(value) } } } : current);\n  const save = async () => {\n    if (!calibration) return;\n    const invalid = rowIds.find((id) => !calibration.measured_rows[id]?.length_m || !calibration.measured_rows[id]?.width_m);\n    if (invalid) { setMessage(`${invalid.replace('row_', 'R')} requires a positive length and width.`); return; }\n    const incomplete = rowIds.find((id) => provenanceProblem(calibration.measured_rows[id] ?? EMPTY_ROW));\n    if (incomplete) { setMessage(`${incomplete.replace('row_', 'R')} ${provenanceProblem(calibration.measured_rows[incomplete] ?? EMPTY_ROW)}.`); return; }"},{"path":"tools/calibration-ui/lib/groundProvenance.ts","line":4,"code":"export function withProvenance<T extends GroundProvenance>(item: T, provenance: MetricMeasurementSource): T {\n  return provenance === 'MEASURED' ? { ...item, provenance, estimation_basis: null } : { ...item, provenance };\n}\n\n/** Why the backend would reject this input's provenance, or null when it is complete. */\nexport function provenanceProblem(item: GroundProvenance): string | null {\n  if (item.provenance === 'MEASURED') return null;\n  if (!(typeof item.uncertainty_m === 'number' && item.uncertainty_m > 0)) return 'needs a positive uncertainty in metres';\n  if (!item.estimation_basis?.trim()) return 'needs an estimation basis';\n  return null;\n}\n"}],"question":"เปลี่ยนจุด P แล้วใช้ผลคำนวณเดิมต่อได้ไหม?","answer":"ต้องคำนวณและตรวจ Calibration ให้ตรงกับค่าปัจจุบันก่อน ผลที่มาจากข้อมูลเดิมไม่ควรถูกถือว่าใช้ได้กับ geometry ใหม่","caution":"ความละเอียดภาพ มุมกล้อง จุด P และแถวต้องสอดคล้องกัน"},{"id":"seg","group":"หาที่ว่าง","title":"06 · Seg ให้ทั้งกรอบและรูปร่างรถ","intro":"YOLO-seg ให้ Bounding box, confidence และ polygon ของ mask ส่วนจุดสีเหลืองคำนวณจากกึ่งกลางขอบล่างของกรอบ","steps":[["Bounding box","x,y คือมุมซ้ายบน width,height คือขนาดกรอบ ในข้อมูลนี้ใช้สัดส่วนของภาพ"],["Mask","polygon บอกบริเวณรูปร่างรถที่มองเห็น ใช้เป็นหลักฐานภาพประกอบการวิเคราะห์"],["จุดสีเหลือง","x = bbox.x + width/2 และ y = bbox.y + height เป็นจุดอ้างอิงโดยประมาณ ไม่ใช่ล้อที่ AI ตรวจพบ"],["โมเดล","ค่าเริ่มต้นใน parking_inference_settings.py ชี้ไป YOLO26n-seg checkpoint แต่ environment อาจเปลี่ยนตัวที่โหลดได้"]],"files":[{"path":"apps/vision-api/app/services/segmentation_experiment_service.py","line":70,"code":"    def __init__(self, model_path: Path | None = None, class_id: int | None = None):\n        self.model_path = model_path if model_path is not None else segmentation_model_path()\n        self.imgsz = int(os.getenv(\"PARKMAP_SEGMENTATION_IMGSZ\", os.getenv(\"PARKMAP_MODEL_IMGSZ\", \"960\")))\n        self.confidence = float(os.getenv(\"PARKMAP_MODEL_CONF\", \".25\"))\n        self.iou = float(os.getenv(\"PARKMAP_MODEL_NMS_IOU\", \".50\"))\n        self.device = os.getenv(\"PARKMAP_DEVICE\", \"cpu\")\n        self.class_id = class_id if class_id is not None else int(os.getenv(\"PARKMAP_SEGMENTATION_CLASS_ID\", str(SEGMENTATION_MOTORCYCLE_CLASS_ID)))\n        self._model = None\n        self._lock = Lock()\n\n    def _load_model(self):\n        if self._model is not None:\n            return self._model\n        if not self.model_path.is_file():\n            raise ModelUnavailableError(\"Local segmentation weights are missing.\")\n        try:\n            model = YOLO(str(self.model_path), task=\"segment\")\n            if model.task != \"segment\" or str(model.names.get(self.class_id, \"\")).strip().lower() != \"motorcycle\":\n                raise ValueError(\"Expected segmentation weights with the configured motorcycle class\")\n        except Exception as error:\n            raise ModelUnavailableError(\"Local segmentation model is unavailable.\") from error\n        self._model = model"},{"path":"tools/calibration-ui/components/parking/SegmentationExperiment.tsx","line":100,"code":"        {showBoxes && result.detections.map((item, index) => <rect key={`bbox-${index}`} data-segmentation-bbox={`detection_${index+1}`} x={item.bbox.x} y={item.bbox.y} width={item.bbox.width} height={item.bbox.height} fill=\"none\" stroke=\"#2563eb\" strokeDasharray=\".006 .004\" strokeWidth=\".002\"><title>Bounding box {index+1} · กว้าง {(item.bbox.width*result.image_width).toFixed(0)} px · {(item.confidence*100).toFixed(1)}%</title></rect>)}\n        {result.detections.map((item, index) => <g key={index}>{item.polygon ? <polygon points={item.polygon.map(point => `${point.x},${point.y}`).join(' ')} fill=\"rgba(6,182,212,.22)\" stroke=\"#06b6d4\" strokeWidth=\".002\"><title>Seg {index + 1} · {(item.confidence * 100).toFixed(1)}%</title></polygon> : <rect x={item.bbox.x} y={item.bbox.y} width={item.bbox.width} height={item.bbox.height} fill=\"none\" stroke=\"#f59e0b\" strokeDasharray=\".006 .004\" strokeWidth=\".002\"><title>Seg {index + 1} · ไม่มี mask</title></rect>}</g>)}\n        {result.detections.map((item, index) => <circle key={`anchor-${index}`} data-ground-anchor={`detection_${index+1}`} cx={item.bbox.x+item.bbox.width/2} cy={item.bbox.y+item.bbox.height} r=\".003\" fill=\"#facc15\" stroke=\"#0f172a\" strokeWidth=\".001\"><title>จุดกึ่งกลางล่าง · detection_{index+1} · {gaps?.occupied_layers.find(layer => layer.detection_index === index)?.assigned_row_id ?? 'ยังระบุแถวไม่ได้'}</title></circle>)}\n      </svg>"}],"question":"Bounding box ต่างจาก mask อย่างไร?","answer":"กรอบเป็นสี่เหลี่ยมครอบวัตถุ ส่วน mask ตามรูปร่างที่ตรวจพบ รถเอียงหรือกระจกยื่นทำให้ความกว้างกรอบไม่ตรงกับความกว้างตัวรถ","caution":"การไม่ตรวจพบรถไม่ใช่หลักฐานว่าบริเวณนั้นว่าง"},{"id":"width","group":"หาที่ว่าง","title":"07 · แปลงขอบกรอบ Seg เป็นเมตรโดยตรง","intro":"ระบบแปลงจุดซ้ายและขวาของขอบล่าง Bounding box ผ่าน Homography แล้ววัดระยะระหว่างพิกัดพื้นทั้งสอง ไม่ใช้ช่วง ±16 px หรือคูณขยายสเกลตรงกลางอีกแล้ว","steps":[["เลือกสองจุด","ซ้าย = (bbox.x, bbox.y + bbox.height) ขวา = (bbox.x + bbox.width, bbox.y + bbox.height) ทั้งคู่ใช้พิกัดสัดส่วนภาพ"],["ตรวจขอบเขต","กรอบต้องอยู่ในภาพ matrix ต้องใช้ได้ และขอบล่างต้องไม่ตัดผ่าน projective horizon ซึ่งทำให้ระยะบนพื้นไม่จำกัด"],["แปลงเป็นเมตร","transform_point แปลงสองจุดผ่าน Homography เดียวกับ Calibration โดยไม่ต้องแปลงสัดส่วนภาพเป็น pixel ก่อน"],["วัดระยะ","math.dist(left_ground, right_ground) ได้ระยะประมาณเป็นเมตร รับเฉพาะค่าจำกัดที่มากกว่า 0 และไม่เกิน 3 เมตร"]],"files":[{"path":"apps/vision-api/app/services/motorcycle_width_estimation.py","line":17,"code":"def estimate_width_m(bbox: DetectionBBox, image_width: int, image_height: int, matrix: np.ndarray) -> float | None:\n    \"\"\"Project the full bbox bottom edge and measure its ground-plane span.\n\n    A camera bbox is not a measured body/mirror width, even when the ground\n    calibration is measured.\n    \"\"\"\n    if image_width <= 0 or image_height <= 0 or matrix.shape != (3, 3) or not np.all(np.isfinite(matrix)):\n        return None\n    if abs(np.linalg.det(matrix)) < 1e-12 or np.linalg.cond(matrix) > 1e12:\n        return None\n    left, right = bbox.x, bbox.x + bbox.width\n    bottom = bbox.y + bbox.height\n    if not 0 <= left < right <= 1 or not 0 <= bbox.y < bottom <= 1:\n        return None\n    # An edge crossing the projective horizon has no finite ground span.\n    denominators = [matrix[2, 0] * x + matrix[2, 1] * bottom + matrix[2, 2] for x in (left, right)]\n    if denominators[0] * denominators[1] <= 0:\n        return None\n    points = [transform_point(x, bottom, matrix) for x in (left, right)]\n    if any(point is None for point in points):\n        return None\n    estimate = math.dist(points[0], points[1])\n    return estimate if math.isfinite(estimate) and 0 < estimate <= 3 else None\n\n\ndef estimate_widths(boxes: Sequence[DetectionBBox], image_width: int, image_height: int,\n                    config_directory: Path) -> dict[int, float]:\n    \"\"\"Return estimates only for a current calibration of this frame's resolution.\"\"\""},{"path":"apps/vision-api/app/services/segmentation_gap_service.py","line":1147,"code":"        estimated_widths = {f\"detection_{index+1}\": width for index, detection in enumerate(detections)\n            if use_segmentation_widths and (width := estimate_width_m(detection.bbox, standard.image_width, standard.image_height, matrix)) is not None}\n        sizes = []\n        for index in indices:\n            width = estimated_widths.get(f\"detection_{index+1}\")\n            sizes.append(ReferenceDimensions(width_m=width if width is not None else WIDTH_M, length_m=LENGTH_M,\n                basis=\"ESTIMATED_SEGMENTATION_WIDTH\" if width is not None else \"STANDARD_SEGMENTATION_REFERENCE\"))\n        analysis = _restore_source_detection_ids(service.analyze(combined, reference_sizes=sizes), indices)\n        # Outside-row vehicles remain image occluders, never synthetic ground\n        # obstacles whose arbitrary reference length reserves another row."}],"question":"ยังต้องใช้ ±16 px หาสเกลไหม?","answer":"ไม่ต้องแล้ว โค้ดใช้ขอบซ้าย–ขวาของกรอบที่ระดับล่างเดียวกัน แปลงเป็นพิกัดพื้นแล้ววัดระยะโดยตรง ถ้าคำนวณไม่ได้ ส่วนเรียกใช้ยัง fallback ไปขนาดอ้างอิง","caution":"เป็นความกว้างกรอบที่ประมาณบนระนาบพื้น ไม่ใช่การวัดความกว้างตัวรถหรือกระจกจริง รถเอียงและความสูงยังทำให้คลาดเคลื่อนได้"},{"id":"gaps","group":"หาที่ว่าง","title":"08 · ช่องว่างเกิดจากโค้ดส่วนไหน","intro":"analyze_segmentation_gaps รวม Calibration, แถว, รถและ mask เพื่อประเมินช่องว่าง ส่วนพื้นที่ที่ดูว่างในภาพยังต้องผ่านเงื่อนไขอื่นก่อน","steps":[["โหลด Calibration","ตรวจให้ข้อมูลพื้นและขนาดภาพตรงกับรอบวิเคราะห์"],["จัดรถเข้าแถว","ใช้จุดอ้างอิงและหลักฐานภาพ เลี่ยงการเลือกแถวที่กำกวมเป็นผลที่แน่นอน"],["สร้าง geometry","สร้างพื้นที่รถตาม reference dimensions แล้วใช้ geometry เพื่อหาพื้นที่/ช่วงที่เหลือ"],["วัดและประเมิน","evaluate_gap_geometry ตรวจความกว้าง ระยะเผื่อ การบัง ความไม่แน่นอน และสร้างผลลัพธ์ให้หน้าเว็บ"]],"files":[{"path":"apps/vision-api/app/services/segmentation_gap_service.py","line":1074,"code":"def analyze_segmentation_gaps(standard: DetectionResponse, segmentation: SegmentationExperimentResult, service=parking_analysis_service, *, reference_sizes=None, incoming_width_m=None, clearance_margin_m=0., visible_free_shapes=False, bottom_edge_assignment=False, image_row_assignment=False, use_segmentation_widths=False):\n    if incoming_width_m is not None and (not math.isfinite(incoming_width_m) or not 0 < incoming_width_m <= 5):\n        raise ValueError(\"Incoming width must be positive and at most 5 metres\")\n    if not math.isfinite(clearance_margin_m) or not 0 <= clearance_margin_m <= 1:\n        raise ValueError(\"Total lateral margin must be between 0 and 1 metre\")\n    try:\n        directory = service.root / \"config\"\n        version = calibration_version(directory)\n        ground = GroundPlaneCalibration.model_validate_json((directory / \"ground_plane_calibration.json\").read_bytes())\n        parking = ParkingCalibration.model_validate_json((directory / \"parking_calibration.json\").read_bytes())\n        response = GroundPlaneHomographyService(directory).get_response(ground)\n        if not response.current or not response.row_validation_current or response.status != \"VALIDATED\" or response.result is None or len(ground.control_points) < 4:\n            raise ValueError(\"Current validated calibration required\")\n        reference = ground.reference_image\n        if parking.camera_id != ground.camera_id or parking.reference_image != reference or (reference.width, reference.height) != (standard.image_width, standard.image_height) or (segmentation.image_width, segmentation.image_height) != (standard.image_width, standard.image_height):\n            raise ValueError(\"Frame and camera calibration must match\")\n        if any(row.id not in ground.measured_rows or ground.measured_rows[row.id].width_m is None or ground.measured_rows[row.id].length_m is None for row in parking.rows):\n            raise ValueError(\"Every row needs metric dimensions\")\n        matrix = np.asarray(response.result.matrix)\n        inverse = np.asarray(response.result.inverse_matrix)\n        if matrix.shape != (3, 3) or inverse.shape != (3, 3) or not np.all(np.isfinite(matrix)) or abs(np.linalg.det(matrix)) < 1e-12 or np.linalg.cond(matrix) > 1e12 or not np.allclose(matrix @ inverse, np.eye(3), atol=1e-6):\n            raise ValueError(\"Invalid calibrated transform\")\n        projected_roi = [transform_point(point.x, point.y, matrix) for point in parking.parking_roi.polygon]"},{"path":"apps/vision-api/app/services/segmentation_gap_service.py","line":1160,"code":"        result = evaluate_gap_geometry(analysis, response.result.inverse_matrix, occluders, evidence_count=evidence, calibration_source=ground.provenance, continuous_gaps=True, slot_width_m=target, clearance_margin_m=clearance_margin_m, primary_count=0, localize_row_uncertainty=True, near_fit_advisories=True, image_occluder_details=occluder_details, visible_free_shapes=visible_free_shapes, row_owned_references=not visible_free_shapes, row_bottom_edges=bottom_edges, row_mask_support=row_mask_support, image_row_assignments=image_assignments)\n        result.occupancy_source = \"SEGMENTATION_ONLY\"\n        result.occupancy_scope = \"IMAGE_NEAREST_LOWER_EDGE\" if image_row_assignment else \"BOTTOM_EDGE_ANCHOR\" if bottom_edges is not None else \"GROUND_ANCHOR_OR_ROW_MASK\"\n        layers_by_id = {layer.detection_id: layer for layer in result.occupied_layers}\n        for assignment in row_assignments:\n            layer = layers_by_id.get(assignment.detection_id)\n            if layer is not None:\n                assignment.assigned_row_id = layer.assigned_row_id\n                assignment.reason = layer.row_assignment_reason\n        result.detection_row_assignments = row_assignments\n        result.horizontal_vehicles = horizontal_vehicle_clearances(segmentation, matrix, inverse, roi)\n        result.excluded_detection_ids = [f\"detection_{index+1}\" for index in range(len(detections)) if index not in indices]"}],"question":"พื้นที่เหลือมาก แปลว่าจอดได้เสมอไหม?","answer":"ไม่เสมอ พื้นที่รวมอาจกระจายเป็นช่องแคบหรือมีรถบัง ต้องดูรูปทรง ความกว้างและข้อจำกัดที่โค้ดประเมิน ผล preview ด้านความกว้างยังไม่ใช่หลักฐานว่าขี่เข้าไปจอดได้ครบทุกเงื่อนไข","caution":"อย่าสรุปว่าระบบตรวจทางเข้าออกหรือความลึกครบ ถ้าโหมดปัจจุบันประเมินเพียงความกว้าง"},{"id":"uncertain","group":"หาที่ว่าง","title":"09 · การบังและความไม่แน่นอน","intro":"ว่างเชิงเรขาคณิต กับมีหลักฐานว่าจอดได้ เป็นคนละเรื่อง รถอาจบังพื้น และภาพอาจเก่าหรือ Calibration ใช้ไม่ได้","steps":[["AVAILABLE","สถานะพร้อมใช้งานต้องมีหลักฐานตามสัญญา backend ไม่ใช่เพียง browser วาดสีเขียว"],["ALMOST_AVAILABLE","คำแนะนำว่าอาจต้องขยับรถ ไม่ใช่คำรับรองให้เคลื่อนรถของผู้อื่น"],["UNKNOWN","ข้อมูลไม่พอ เก่า ถูกบัง หรือไม่ผ่านการตรวจ ต้องไม่ตีความเป็นว่าง"],["UNMONITORED","พื้นที่นอกการติดตาม ไม่มีคำอ้างเรื่องที่ว่าง"]],"files":[{"path":"tools/calibration-ui/components/parking/GapOcclusionInspector.tsx","line":18,"code":"export function GapOcclusionOverlay({ gap, result, evidence = gap.occlusion_evidence, sources = relatedSources(gap) }: { gap: Selection; result: Result; evidence?: Evidence[]; sources?: Source[] }) {\n  const geometry = imageGeometry(gap);\n  return <g className=\"pointer-events-none\" data-image-inspection={gap.id}>\n    {sources.map(item => {\n      const source = result.detections[item.detection_index];\n      const overlap = evidence.find(entry => entry.detection_id === item.detection_id);\n      return <g key={item.detection_id} data-related-detection={item.detection_id} data-occluding-detection={overlap ? item.detection_id : undefined}>\n        {source && (item.source_kind === 'MASK' && source.polygon ? <polygon points={points(source.polygon)} fill=\"none\" stroke=\"#ea580c\" strokeWidth=\"2.5\" vectorEffect=\"non-scaling-stroke\" />\n          : <rect x={source.bbox.x} y={source.bbox.y} width={source.bbox.width} height={source.bbox.height} fill=\"none\" stroke=\"#ea580c\" strokeWidth=\"2.5\" strokeDasharray=\"6 4\" vectorEffect=\"non-scaling-stroke\" />)}\n        {overlap?.overlap_image.polygons.map((rings, index) => <path key={index} data-occlusion-overlap={item.detection_id} d={path(rings)} fill=\"#e879f9\" fillOpacity=\".75\" fillRule=\"evenodd\" stroke=\"#86198f\" strokeWidth=\"1.5\" vectorEffect=\"non-scaling-stroke\"><title>{item.detection_id} · ส่วนที่ทับบริเวณที่เลือกในภาพ</title></path>)}\n      </g>;\n    })}\n    {geometry?.polygons.map((rings, index) => <path key={index} d={path(rings)} fill=\"none\" fillRule=\"evenodd\" stroke=\"#1d4ed8\" strokeWidth=\"2.5\" vectorEffect=\"non-scaling-stroke\" />)}\n  </g>;\n}\n\nexport function GapOcclusionInspector({ gap, result, showOverlay, onShowOverlay }: {\n  gap: Selection; result: Result; showOverlay: boolean; onShowOverlay: (value: boolean) => void;\n}) {\n  const [focus, setFocus] = useState<{ gap: Selection; detectionId: string } | null>(null);"},{"path":"apps/vision-api/app/services/uncertainty_service.py","line":10,"code":"def calculate_uncertainty(rows: list[tuple[str, Polygon]], included: list[tuple[dict[str, Any], Polygon, tuple[Any, ...]]]) -> dict[str, Any]:\n    by_row = {row_id: {\"row_id\": row_id, \"status\": \"CLEAR\", \"affected_detection_ids\": [], \"reasons\": [], \"evidence\": [], \"validation\": True} for row_id, _ in rows}\n    for item, footprint, assignment in included:\n        state = assignment[1]\n        if state not in {\"AMBIGUOUS\", \"UNASSIGNED\"}:\n            continue\n        reason = \"AMBIGUOUS_ROW_ASSIGNMENT\" if state == \"AMBIGUOUS\" else \"UNASSIGNED_ROW_INTERSECTION\"\n        if footprint.is_empty or not footprint.is_valid:\n            continue\n        for row_id, row in rows:\n            area = footprint.intersection(row).area\n            if area <= EPSILON:\n                continue\n            target = by_row[row_id]\n            target[\"status\"] = \"UNCERTAIN\"\n            detection_id = item[\"detection_id\"]\n            if detection_id not in target[\"affected_detection_ids\"]:\n                target[\"affected_detection_ids\"].append(detection_id)\n            if reason not in target[\"reasons\"]:\n                target[\"reasons\"].append(reason)\n            evidence = {\"detection_id\": detection_id, \"reason\": reason, \"affected_row_id\": row_id, \"intersection_area_m2\": area}\n            if not any(e[\"detection_id\"] == detection_id and e[\"reason\"] == reason for e in target[\"evidence\"]):\n                target[\"evidence\"].append(evidence)\n    output = list(by_row.values())"}],"question":"ทำไมจึงต้องมี UNKNOWN?","answer":"เพื่อแยกไม่มีหลักฐานออกจากว่าง ถ้าใช้ภาพเก่าหรือมองไม่เห็นพื้น การแสดงว่าว่างอาจทำให้ผู้ใช้ขี่เข้าไปแล้วจอดไม่ได้","caution":"สีและชื่อในหน้าทดลองอาจเป็นสถานะเฉพาะการวิเคราะห์ ต้องดู mapping ไป API ก่อนอธิบายว่าเป็นสถานะใช้งานจริง"},{"id":"shared","group":"หาที่ว่าง","title":"10 · Calibration กับ LIFF ใช้โค้ดเดียวกันไหม","intro":"ทั้งเส้นทาง operator แบบ Segmentation และ worker เรียก analyze_segmentation_gaps ร่วมกัน แต่ข้อมูลนำเข้า เวลา และขั้นตอนแสดงผลต่างกัน","steps":[["Calibration","classifier.py เรียก detector แล้ว analyze_segmentation_gaps ส่งผลกลับหน้า Parking"],["Worker","frame_analysis_service.py วิเคราะห์ภาพ แล้ว build_segmentation_state_publish เพื่อส่ง state เข้า API"],["LIFF","อ่าน parking-state และนำไปแสดง มีการแปลงสู่พิกัด lot และนโยบายความสดของข้อมูล"],["เงื่อนไขเปรียบเทียบ","ต้องเทียบภาพ โมเดล พารามิเตอร์ Calibration และเวลาเดียวกัน ไม่เช่นนั้นผลอาจต่าง"]],"files":[{"path":"apps/vision-api/app/classifier.py","line":348,"code":"async def analyze_segmentation_primary(decoded, raw, include_parking, incoming_width_m, clearance_margin_m, detector, *, imgsz=None):\n    \"\"\"One Seg inference supplies every operator Parking view; no classifier.\"\"\"\n    try:\n        if imgsz is None:\n            segmented = await run_in_threadpool(detector.analyze_image, raw)\n        else:\n            segmented = await run_in_threadpool(detector.analyze_frame, decoded, imgsz=imgsz)\n    except (ModelUnavailableError, OSError, ValueError, RuntimeError) as error:\n        raise HTTPException(503, \"Segmentation unavailable; verify configured local segmentation weights and settings.\") from error\n    segmented.preview_url = encode_preview(decoded)\n    detection = detector.detection_response(segmented)\n    result = ParkingClassifierResult(detection=detection, segmentation=segmented)\n    if include_parking:\n        try:\n            detection.parking_analysis = await run_in_threadpool(parking_analysis_service.analyze, detection)\n        except ParkingCalibrationUnavailableError:\n            result.parking_error = \"Parking calibration is unavailable; segmentation remains usable.\"\n    result.segmentation_gaps = await run_in_threadpool(analyze_segmentation_gaps, detection, segmented,\n        incoming_width_m=incoming_width_m, clearance_margin_m=clearance_margin_m, visible_free_shapes=False, bottom_edge_assignment=True, image_row_assignment=True, use_segmentation_widths=True)\n    if result.segmentation_gaps.status != \"CALIBRATION_REQUIRED\":\n        widths = {index: result.segmentation_gaps.estimated_widths_m[f\"detection_{index+1}\"]\n            for index in range(len(segmented.detections)) if f\"detection_{index+1}\" in result.segmentation_gaps.estimated_widths_m}\n        result.motorcycles, _ = build_segmentation_display(segmented, result.segmentation_gaps, estimated_widths=widths)"},{"path":"apps/vision-api/app/services/frame_analysis_service.py","line":25,"code":"def analyze_segmentation_frame(image, captured_at: datetime, *, parking_area_id: str, source: StateSourceKind) -> ParkingStatePublish:\n    version, provenance = calibration_identity(CONFIG_DIRECTORY)\n    encoded, jpeg = cv2.imencode(\".jpg\", image)\n    if not encoded:\n        raise ValueError(\"Frame could not be encoded.\")\n    segmented = segmentation_experiment_service.analyze_image(jpeg.tobytes())\n    detection = DetectionResponse(image_width=segmented.image_width, image_height=segmented.image_height,\n        model={\"name\": segmented.model}, inference={\"imgsz\": segmented.imgsz,\n            \"confidence_threshold\": segmentation_experiment_service.confidence,\n            \"nms_iou\": segmentation_experiment_service.iou, \"processing_time_ms\": segmented.processing_time_ms},\n        detections=[Detection(class_id=segmentation_experiment_service.class_id, class_name=\"motorcycle\",\n            confidence=item.confidence, bbox=item.bbox) for item in segmented.detections])\n    gaps = analyze_segmentation_gaps(detection, segmented, visible_free_shapes=False,\n        bottom_edge_assignment=True, image_row_assignment=True, use_segmentation_widths=True)\n    try:\n        camera = ParkingCalibration.model_validate_json((CONFIG_DIRECTORY / \"parking_calibration.json\").read_bytes()).camera_id\n    except (OSError, ValidationError) as error:\n        raise CalibrationFilesUnavailableError(\"Parking calibration is unavailable or invalid\") from error\n    estimated_widths = {index: gaps.estimated_widths_m[f\"detection_{index+1}\"]\n        for index in range(len(segmented.detections)) if f\"detection_{index+1}\" in gaps.estimated_widths_m}\n    if calibration_identity(CONFIG_DIRECTORY) != (version, provenance):\n        raise CalibrationFilesUnavailableError(\"Calibration changed during worker analysis\")\n    return build_segmentation_state_publish(\n        segmented, gaps,\n        camera_id=camera,\n        parking_area_id=parking_area_id,\n        source=source,\n        observed_at=captured_at,\n        processed_at=datetime.now(UTC),\n        calibration_version=version,"}],"question":"อธิบายว่าใช้โค้ดเดียวกันได้ไหม?","answer":"ได้ โดยเจาะจงว่าใช้แกนคำนวณช่องว่าง analyze_segmentation_gaps ร่วมกัน หน้าเว็บและขั้นตอนรับภาพไม่ใช่โค้ดชุดเดียวทั้งหมด","caution":"การย้ายหรือย่อแผนผังสำหรับแสดงผลไม่ควรเปลี่ยนระยะกายภาพที่ใช้วิเคราะห์"},{"id":"lot","group":"Lot Model Editor","title":"11 · แผนผังสถานที่และ landmark","intro":"Lot Model เป็นแผนผังคงที่ของสถานที่ ประกอบด้วย outline, parking_areas และ landmarks ไม่ใช่โมเดลที่สร้างรูปทรงจริงจากกล้องหนึ่งภาพ","steps":[["Outline","ขอบเขตของลานที่ใช้เป็นกรอบของแผนผัง"],["Parking areas / ROI","polygon ของพื้นที่ที่กล้องรับผิดชอบ ต้องอยู่ในขอบลานและไม่ทับกันอย่างผิดเงื่อนไข"],["Landmark","สิ่งอ้างอิง เช่น อาคาร ต้นไม้ ทางเดิน ทางเข้า ช่วยให้ผู้ใช้เทียบแผนที่กับสถานที่"],["2D / 3D","แก้พิกัดและคุณสมบัติผ่าน canvas ดู preview 3D จาก geometry เดียวกัน"]],"files":[{"path":"tools/calibration-ui/components/lot-model/LotModelEditor.tsx","line":15,"code":"function definitionOnly(definition: LotModelDefinition): LotModelDefinition {\n  return { schema_version: definition.schema_version ?? 1, outline: definition.outline, parking_areas: definition.parking_areas, landmarks: definition.landmarks ?? [] };\n}\n\nasync function request<T>(operation: string, site = '', method = 'GET', body?: unknown, signal?: AbortSignal): Promise<T> {\n  const query = new URLSearchParams({ op: operation, ...(site ? { site } : {}) });"},{"path":"tools/calibration-ui/lib/lotModelEditor.ts","line":167,"code":"export function newLandmark(model: LotModelDefinition, kind: LandmarkKind, position: MetricPoint): LotLandmark {\n  const ids = new Set((model.landmarks ?? []).map((landmark) => landmark.landmark_id));\n  if (ids.size >= 100) throw new Error('หนึ่งแผนผังเพิ่มวัตถุได้ไม่เกิน 100 รายการ');\n  const prefix = kind.toLowerCase().replaceAll('_', '-');\n  let number = 1;\n  while (ids.has(`${prefix}-${number}`)) number++;\n  const base: LotLandmark = { landmark_id: `${prefix}-${number}`, kind, position, measurement_source: 'ESTIMATED' };\n  if (kind === 'TREE') return { ...base, height_m: 6, radius_m: 2 };\n  if (kind === 'BARRIER') return { ...base, line: [{ x_m: position.x_m - 2, y_m: position.y_m }, { x_m: position.x_m + 2, y_m: position.y_m }] };\n  if (kind === 'ENTRANCE' || kind === 'EXIT' || kind === 'ENTRANCE_EXIT') return base;\n  const width = kind === 'ROAD' ? 6 : kind === 'BUILDING' ? 8 : 2;\n  const length = kind === 'ROAD' ? 20 : 10;\n  const x = position.x_m, y = position.y_m;\n  return {\n    ...base,\n    polygon: [[{ x_m: x - width / 2, y_m: y - length / 2 }, { x_m: x + width / 2, y_m: y - length / 2 },\n      { x_m: x + width / 2, y_m: y + length / 2 }, { x_m: x - width / 2, y_m: y + length / 2 }]],\n    ...(['BUILDING', 'GUARD_BOOTH', 'SHELTER'].includes(kind) ? { height_m: 3 } : {}),\n    ...(kind === 'PLANTING' ? { height_m: 0.5 } : {}),\n  };\n}\n"}],"question":"ทำไมต้องมี landmark?","answer":"ช่วยให้ผู้ใช้รู้ว่าตำแหน่งในแผนที่ตรงกับส่วนไหนของสถานที่จริง แต่ landmark ไม่ได้ให้หลักฐานว่าตรงนั้นมีที่จอดว่าง","caution":"แยกค่าประมาณของแผนผังออกจากข้อมูลสำรวจ อย่าอธิบายว่าภาพ 3D คือการสร้างรถจริงจากกล้อง"},{"id":"edit","group":"Lot Model Editor","title":"12 · ย้าย หมุน ย่อขยาย และ Undo","intro":"การแก้รูปทรงคือการแก้จุดพิกัดในข้อมูล React ส่วน canvas เป็นผู้วาดข้อมูลนั้นออกมา","steps":[["ย้าย","moveLandmark ปรับตำแหน่งและจุด polygon ตามระยะที่เปลี่ยน"],["หมุน","rotatePolygonObject ใช้ sin/cos หมุนทุกจุดรอบตำแหน่งอ้างอิงของวัตถุ"],["ย่อขยาย","scalePolygonObject ขยายระยะจากศูนย์กลางด้วย factor เดียว รักษารูปร่างและวง polygon"],["Undo / Redo","history มี past, present, future เปลี่ยนข้อมูลที่แสดงโดยยังไม่จำเป็นต้องบันทึก server"]],"files":[{"path":"tools/calibration-ui/lib/lotModelEditor.ts","line":35,"code":"export function rotatePolygonObject(object: LotLandmark, degrees: number): LotLandmark {\n  if (!Number.isFinite(degrees)) throw new Error('มุมต้องเป็นตัวเลขที่มีค่าจำกัด');\n  if (!degrees) return object;\n  const radians = (degrees % 360) * Math.PI / 180;\n  const c = Math.cos(radians), s = Math.sin(radians);\n  const rotate = (point: MetricPoint): MetricPoint => ({\n    x_m: object.position.x_m + (point.x_m - object.position.x_m) * c - (point.y_m - object.position.y_m) * s,\n    y_m: object.position.y_m + (point.x_m - object.position.x_m) * s + (point.y_m - object.position.y_m) * c,\n  });\n  return { ...object, polygon: object.polygon?.map((ring) => ring.map(rotate)) };\n}\n\n/** Uniform scale about the ROI centre; preserve every ring and its orientation. */\nexport function scalePolygonObject(object: LotLandmark, factor: number): LotLandmark {\n  if (!Number.isFinite(factor) || factor <= 0) throw new Error('อัตราขยายต้องมากกว่า 0');\n  if (!object.polygon) throw new Error('ต้องเลือกพื้นที่รูปหลายเหลี่ยม');\n  return { ...object, polygon: object.polygon.map(ring => ring.map(point => ({\n    x_m: object.position.x_m + (point.x_m-object.position.x_m)*factor,\n    y_m: object.position.y_m + (point.y_m-object.position.y_m)*factor,\n  }))) };\n}\n\nexport interface RectangleDimensions {\n  width: number;"},{"path":"tools/calibration-ui/components/lot-model/LotModelEditor.tsx","line":43,"code":"interface History { past: LotModelDefinition[]; present: LotModelDefinition | null; future: LotModelDefinition[] }\n\nexport function LotModelEditor() {\n  const [history, setHistory] = useState<History>({ past: [], present: null, future: [] });\n  const [template, setTemplate] = useState<LotModelDefinition | null>(null);\n  const [sites, setSites] = useState<SiteSummary[]>([]);\n  const [siteId, setSiteId] = useState('');\n  const [server, setServer] = useState<LotModelDraftState | null>(null);\n  const [selectedId, setSelectedId] = useState<string | null>(null);\n  const [newKind, setNewKind] = useState<LandmarkKind>('TREE');\n  const [mode, setMode] = useState<'2d' | '3d'>('2d');\n  const [editRoi, setEditRoi] = useState(false);\n  const [busy, setBusy] = useState(true);\n  const [error, setError] = useState('');\n  const [notice, setNotice] = useState('');\n  const form = useRef<HTMLFormElement>(null);"}],"question":"กดหมุนบนจอแล้วข้อมูลเปลี่ยนอย่างไร?","answer":"ฟังก์ชันคำนวณพิกัดใหม่ของทุกจุดรอบศูนย์กลาง แล้วคืน object ใหม่ให้ state React canvas จึงวาดตามข้อมูลใหม่ ไม่ได้หมุนเพียงภาพหน้าจอ","caution":"uniform display scale เป็นการปรับการแสดงแผนผัง ไม่ใช่การวัดพื้นที่จริงใหม่"},{"id":"save","group":"Lot Model Editor","title":"13 · Save draft ต่างจาก Activate","intro":"บันทึกฉบับร่างเพื่อแก้ต่อได้ ส่วน Activate คือเปิดเวอร์ชันให้ LIFF ใช้ ระบบตรวจ revision เพื่อป้องกันการเขียนทับงานเก่า","steps":[["Save draft","ส่ง definition, expected_revision และ base_version ผ่าน proxy ไป backend"],["ตรวจ API","ตรวจสิทธิ์และ validate geometry พร้อมตรวจความสอดคล้องของเวอร์ชัน"],["Activate","ต้องบันทึกก่อน เปิดใช้ draft ที่ตรวจแล้วเป็น lot-model version ใหม่"],["ผลกับ LIFF","LIFF ยังอ่าน active version เดิมจนกว่าจะ activate และโหลดข้อมูลใหม่"]],"files":[{"path":"tools/calibration-ui/components/lot-model/LotModelEditor.tsx","line":181,"code":"  async function save() {\n    if (!model || !server || busy || stale || !form.current?.reportValidity()) return;\n    setBusy(true); setError(''); setNotice('');\n    try {\n      const draft = await request<LotModelDraftState>('draft', siteId, 'PUT', { definition: model, expected_revision: server.revision, base_version: server.base_version });\n      setServer(draft); replace(draft.definition); setNotice('บันทึกฉบับร่างแล้ว LIFF ยังใช้เวอร์ชันเดิม');\n    } catch (cause) { setError(cause instanceof Error ? cause.message : 'บันทึกไม่ได้'); }\n    finally { setBusy(false); }\n  }\n\n  async function activate() {\n    if (!server || busy || dirty || stale || !form.current?.reportValidity()) return;\n    const name = sites.find((site) => site.site_id === siteId)?.name ?? siteId;\n    if (!window.confirm(`เปิดใช้ฉบับร่างของ ${name} ใน LIFF หรือไม่?\\nแผนผังที่นักศึกษาเห็นจะเปลี่ยนเป็นฉบับนี้\\nรถและแถวจะย้าย หมุน และย่อ–ขยายตาม ROI โดยคงระยะวิเคราะห์เดิม หากรูปทรงเปลี่ยนต้องตรวจ calibration ใหม่`)) return;\n    setBusy(true); setError(''); setNotice('');\n    try {\n      const published = await request<LotModelDraftState>('activate', siteId, 'POST', { expected_revision: server.revision, base_version: server.base_version });\n      setServer(published); replace(published.definition); setNotice(`เปิดใช้เวอร์ชัน ${published.active_version} แล้ว โหลดหน้า LIFF ใหม่เพื่อดูผล`);\n    } catch (cause) { setError(cause instanceof Error ? cause.message : 'เปิดใช้งานไม่ได้'); }\n    finally { setBusy(false); }\n  }\n\n  function download() {\n    if (!model || !form.current?.reportValidity()) return;\n    const url = URL.createObjectURL(new Blob([`${JSON.stringify(model, null, 2)}\\n`], { type: 'application/json' }));\n    const anchor = document.createElement('a'); anchor.href = url; anchor.download = 'spu-cam-01-lot-model.json'; anchor.click();"},{"path":"apps/vision-api/app/lot_model_editor.py","line":80,"code":"def validate_definition(definition: LotModelDefinition) -> LotModelDefinition:\n    try:\n        validate_lot_model(definition)\n        return definition\n    except ValueError as error:\n        raise HTTPException(422, str(error)) from error\n\n\n@router.post(\"/sites/{site_id}/calibration-roi\", response_model=LotModelDefinition)\ndef post_calibration_roi(definition: LotModelDefinition, site_id: str = ApiPath(pattern=IDENTIFIER_PATTERN), session: Session = SessionDependency) -> LotModelDefinition:\n    try:\n        return preview_calibration_roi(session, site_id, definition)\n    except ValueError as error:\n        raise editor_exception(error) from error\n"},{"path":"tools/calibration-ui/lib/lotModelProxy.ts","line":6,"code":"export interface ProxyOptions {\n  apiUrl: string;\n  token?: string;\n  fetcher?: (url: string, init: RequestInit) => Promise<Response>;\n}\n\nasync function boundedBody(request: Request): Promise<string | null> {\n  if (Number(request.headers.get('Content-Length')) > MAX_BYTES) return null;\n  const reader = request.body?.getReader();\n  if (!reader) return '';\n  const chunks: Uint8Array[] = [];\n  let size = 0;\n  try {\n    while (true) {\n      const chunk = await reader.read();\n      if (chunk.done) break;\n      size += chunk.value.byteLength;\n      if (size > MAX_BYTES) { await reader.cancel(); return null; }\n      chunks.push(chunk.value);\n    }\n  } finally { reader.releaseLock(); }\n  const body = new Uint8Array(size);\n  let offset = 0;\n  for (const chunk of chunks) { body.set(chunk, offset); offset += chunk.byteLength; }\n  return new TextDecoder().decode(body);"}],"question":"ทำไมต้องแยก Save กับ Activate?","answer":"เพื่อให้ปรับและตรวจฉบับร่างก่อนเผยแพร่แก่ผู้ใช้จริง expected_revision และ base_version ช่วยตรวจว่ากำลังแก้จากข้อมูลเก่าหรือไม่ ถ้าไม่ตรงต้องโหลดใหม่","caution":"คู่มือนี้เป็นเว็บอ่านโค้ด การกดตัวอย่างในคู่มือไม่บันทึกหรือเปลี่ยนแผนผังจริง"},{"id":"review","group":"เตรียมอธิบาย","title":"14 · ตามข้อมูลตั้งแต่คลิกจนถึงผลลัพธ์","intro":"เวลาอธิบายให้เริ่มจากปัญหา ตามด้วยข้อมูลเข้า ฟังก์ชันสำคัญ ผลลัพธ์ และข้อจำกัด ไม่ต้องท่องทุกบรรทัด","steps":[["ตั้งค่าพื้น","ภาพ → ROI/แถว → จุด P/ระยะเมตร → คำนวณและตรวจ Homography"],["หาที่ว่าง","ภาพ → YOLO-seg → bbox/mask → พิกัดพื้นและแถว → geometry/ช่องว่าง → แสดงผล"],["แก้แผนผัง","เลือก site → โหลด draft/active model → แก้ landmark/ROI → Save draft → Activate → LIFF"],["ขอบเขตงาน","อธิบาย frontend ที่คุณทำ และ backend ที่เชื่อมต่อ แยกจากความรับผิดชอบเรื่อง training, Label, Route และ Mobile Camera ที่ไม่ได้รวมเป็นบทเฉพาะ"]],"files":[{"path":"tools/calibration-ui/components/setup/SetupWorkspace.tsx","line":3,"code":"import { useState } from 'react';\nimport { LotModelEditor } from '../lot-model/LotModelEditor';\nimport { SetupPage } from './SetupPage';\nimport { MobileCameraSetup } from './MobileCameraSetup';\nimport { RouteEditor } from './RouteEditor';\n\nexport function SetupWorkspace({ initialTab = 'camera' }: { initialTab?: 'camera' | 'lot' | 'mobile' | 'routes' }) {\n  const [tab, setTab] = useState(initialTab);\n  const [visited, setVisited] = useState(() => new Set([initialTab]));\n  return <section className=\"space-y-5\">\n    <div><h1 className=\"text-2xl font-semibold\">Setup สถานที่</h1><p className=\"mt-2 text-sm text-slate-500\">ตั้งค่าแผนผังและกล้องในที่เดียว ปุ่มบันทึกของแต่ละงานแยกกัน ตรวจให้กล้องและสถานที่ที่เลือกตรงกัน</p></div>\n    <div className=\"inline-flex flex-wrap gap-1 rounded-xl border bg-white p-1\" role=\"tablist\" aria-label=\"ตั้งค่าสถานที่\">\n      {([['camera', 'กล้องและ Calibration'], ['lot', 'แผนผังสถานที่'], ['mobile', 'กล้องมือถือ / QR'], ['routes', 'เส้นทาง LIFF']] as const).map(([id, name]) => <button key={id} type=\"button\" role=\"tab\" aria-selected={tab === id}\n        className={`rounded-lg px-4 py-2 text-sm font-medium ${tab === id ? 'bg-blue-600 text-white' : 'text-slate-600 hover:bg-slate-50'}`}\n        onClick={() => { setTab(id); setVisited((old) => new Set([...old, id])); }}>{name}</button>)}\n    </div>\n    <p className=\"text-xs text-slate-500\">ROI บนภาพกล้องใช้กำหนดขอบเขตวิเคราะห์ ส่วน ROI บนแผนผังใช้จัดวางพื้นที่ในหน่วยเมตร</p>\n    {visited.has('camera') && <div hidden={tab !== 'camera'}><SetupPage /></div>}\n    {visited.has('lot') && <div hidden={tab !== 'lot'}><LotModelEditor /></div>}\n    {visited.has('mobile') && <div hidden={tab !== 'mobile'}><MobileCameraSetup /></div>}"}],"question":"ถ้าอาจารย์ถามว่า AI รู้ระยะจริงได้อย่างไร จะตอบว่าอะไร?","answer":"AI ตรวจตำแหน่งรถในภาพ ส่วนหน่วยเมตรมาจาก Calibration ที่เราป้อนคู่จุดภาพกับพิกัดพื้น การประมาณความกว้างแปลงขอบล่างซ้าย–ขวาของกรอบผ่าน Homography แล้ววัดระยะ ไม่ใช่ AI วัดความกว้างจริงโดยตรง","caution":"ตัวอย่างในคู่มือใช้ค่าจำลองเพื่ออธิบาย ไม่ใช่ผลวัดความแม่นยำของระบบ"}]};
